$cs="Server=localhost\SQLEXPRESS;Database=GSDDashboard;Integrated Security=true;TrustServerCertificate=yes;"; $conn=New-Object System.Data.SqlClient.SqlConnection($cs); $conn.Open(); $cmd=$conn.CreateCommand(); $cmd.CommandText="SELECT e.EmployeeId, e.FullName, e.PrimaryRole, e.Bundesland, s.ShiftType, s.ShiftStart, s.ShiftEnd FROM Employees e LEFT JOIN ShiftEntries s ON e.EmployeeId=s.EmployeeId AND s.ShiftDate='2026-06-22' WHERE e.FullName LIKE '%Angelika%Weber%'"; $r=$cmd.ExecuteReader(); while($r.Read()){Write-Host $r[0] '|' $r[1] '|' $r[2] '|' $r[3] '|' $r[4] '|' $r[5] '-' $r[6]}; $conn.Close(); Write-Host "---done---"
